const img_Weekday_l1xq = [
  A('week_w1.png'),
  A('week_w2.png'),
  A('week_w3.png'),
  A('week_w4.png'),
  A('week_w5.png'),
  A('week_w6.png'),
  A('week_w7.png'),
]

const img_Day_x47y = [
  A('font_6_0.png'),
  A('font_6_1.png'),
  A('font_6_2.png'),
  A('font_6_3.png'),
  A('font_6_4.png'),
  A('font_6_5.png'),
  A('font_6_6.png'),
  A('font_6_7.png'),
  A('font_6_8.png'),
  A('font_6_9.png'),
]

const img_Temperature_x1hb = [
  A('font_1_0.png'),
  A('font_1_1.png'),
  A('font_1_2.png'),
  A('font_1_3.png'),
  A('font_1_4.png'),
  A('font_1_5.png'),
  A('font_1_6.png'),
  A('font_1_7.png'),
  A('font_1_8.png'),
  A('font_1_9.png'),
]

WatchFace({
  initView() {
    // the picked variant survives a restart (when the watch offers storage)
    let variantIdx = 0
    try { if (typeof hmFS !== 'undefined') variantIdx = Number(hmFS.SysProGetInt('dialcraft_variant')) || 0 } catch (e) {}

    // layers with a code handle: W.<handle> is the widget, F.<handle> the picture list of a variants layer
    const W = {}
    const F = {}
    // Background (FILL_RECT)
    ui.createWidget(ui.widget.FILL_RECT, {
      x: px(0),
      y: px(0),
      w: px(390),
      h: px(450),
      color: 0x000000,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Liquid (IMG)
    const variants_0 = [A('cocoa_0.png'), A('cocoa_1.png'), A('cocoa_2.png'), A('cocoa_3.png'), A('cocoa_4.png'), A('cocoa_5.png'), A('cocoa_6.png'), A('cocoa_7.png'), A('cocoa_8.png'), A('cocoa_9.png')]
    const variant_0 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: variants_0[variantIdx % variants_0.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.liquid = variant_0
    F.liquid = variants_0

    // Cover (IMG)
    const variants_1 = [A('cover_0.png'), A('cover_1.png'), A('cover_2.png'), A('cover_3.png'), A('cover_4.png'), A('cover_5.png'), A('cover_6.png'), A('cover_7.png'), A('cover_8.png'), A('cover_9.png')]
    const variant_1 = ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(-410),
      src: variants_1[variantIdx % variants_1.length],
      show_level: ui.show_level.ONLY_NORMAL
    })
    W.cover = variant_1
    F.cover = variants_1

    // Minute Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(201),
      minute_startY: px(167),
      minute_zero: 1,
      minute_space: px(-22),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Main_h2ge,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Colon Main (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(167),
      y: px(188),
      src: A('symbol_u003a.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // Hour Main (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(29),
      hour_startY: px(167),
      hour_zero: 1,
      hour_space: px(-22),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Main_h3gu,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Minute Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      minute_startX: px(130),
      minute_startY: px(240),
      minute_zero: 1,
      minute_space: px(0),
      minute_align: ui.align.LEFT,
      minute_array: img_Minute_Aod_u2ef,
      minute_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Hour Aod (IMG_TIME)
    ui.createWidget(ui.widget.IMG_TIME, {
      hour_startX: px(125),
      hour_startY: px(100),
      hour_zero: 1,
      hour_space: px(0),
      hour_align: ui.align.LEFT,
      hour_array: img_Hour_Aod_t7hg,
      hour_follow: 0,
      show_level: ui.show_level.ONLY_AOD,
    })

    // Weekday (IMG_WEEK)
    ui.createWidget(ui.widget.IMG_WEEK, {
      x: px(110),
      y: px(21),
      week_en: img_Weekday_l1xq,
      week_sc: img_Weekday_l1xq,
      week_tc: img_Weekday_l1xq,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Day (IMG_DATE)
    ui.createWidget(ui.widget.IMG_DATE, {
      day_startX: px(198),
      day_startY: px(33),
      day_zero: 0,
      day_space: px(-24),
      day_align: ui.align.LEFT,
      day_follow: 0,
      day_en_array: img_Day_x47y,
      day_sc_array: img_Day_x47y,
      day_tc_array: img_Day_x47y,
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Temperature (TEXT_IMG)
    ui.createWidget(ui.widget.TEXT_IMG, {
      x: px(133),
      y: px(366),
      type: ui.data_type.WEATHER_CURRENT,
      font_array: img_Temperature_x1hb,
      h_space: px(-22),
      align_h: ui.align.LEFT,
      unit_en: A('degree.png'),
      unit_sc: A('degree.png'),
      unit_tc: A('degree.png'),
      negative_image: A('negative.png'),
      show_level: ui.show_level.ONLY_NORMAL,
    })

    // Glass (IMG)
    ui.createWidget(ui.widget.IMG, {
      x: px(0),
      y: px(0),
      src: A('glass_front.png'),
      show_level: ui.show_level.ONLY_NORMAL
    })

    // a Tap zone set to "Cycle variants" calls this
    const cycleVariants = () => {
      variantIdx = (variantIdx + 1) % Math.max(variants_0.length, variants_1.length)
      try { if (typeof hmFS !== 'undefined') hmFS.SysProSetInt('dialcraft_variant', variantIdx) } catch (e) {}
      variant_0.setProperty(ui.prop.SRC, variants_0[variantIdx % variants_0.length])
      variant_1.setProperty(ui.prop.SRC, variants_1[variantIdx % variants_1.length])
    }

    // ---- user code (project.userCode) ----
    // px() only takes a literal number (the build replaces it, there is no px at run time); pxv() scales a computed one
    const pxv = (n) => Math.round(n * px(1000) / 1000)
    {
      const MS = 100, TOP_EMPTY = 450, TOP_FULL = 40
      const NB = F.liquid.length
      let n = 0, id = null, via = '', y = null, lastSec = -1, sub = 0, clock = null
      try { clock = new DCTime() } catch (e) {}
      // seconds of the minute from the Zepp Time sensor (else Date, else our own count)
      const seconds = () => {
        try { if (clock) { const s = clock.getSeconds(); if (typeof s === 'number' && s >= 0) return s } } catch (e) {}
        try { const s = new Date().getSeconds(); if (typeof s === 'number' && s >= 0) return s } catch (e) {}
        return Math.floor(n * MS / 1000) % 60
      }
      // the sensor only counts whole seconds, so the ticks since the second changed fill in the fraction
      const fraction = () => {
        const s = seconds()
        if (s !== lastSec) { lastSec = s; sub = 0 } else sub++
        return (s + Math.min(0.95, sub * MS / 1000)) / 60
      }
      const tick = () => {
        n++
        const ny = Math.round(TOP_EMPTY - (TOP_EMPTY - TOP_FULL) * fraction()) - TOP_EMPTY
        y = ny
        // MORE takes x, y and src together on a plain IMG (checked on a Bip 6); SRC alone did not swap the pictures
        W.cover.setProperty(ui.prop.MORE, { x: 0, y: pxv(y), src: F.cover[n % NB] })
        W.liquid.setProperty(ui.prop.MORE, { x: 0, y: 0, src: F.liquid[n % NB] })
      }
      const stop = () => {
        if (id === null) return
        try { if (via === 't') timer.stopTimer(id); else clearInterval(id) } catch (e) {}
        id = null
      }
      const safe = () => { try { tick() } catch (e) {} }
      const start = () => {
        if (id !== null) return
        try {
          if (typeof timer !== 'undefined' && timer && timer.createTimer) { id = timer.createTimer(0, MS, safe); via = 't' }
          else if (typeof setInterval === 'function') { id = setInterval(safe, MS); via = 'i' }
        } catch (e) {}
      }
      ui.createWidget(ui.widget.WIDGET_DELEGATE, { resume_call: () => { lastSec = -1; start() }, pause_call: stop })
      safe()
      start()
    }
  },

  build() {
    this.initView()
  },
})
